import{_ as s,o as t,c as e,ae as a}from"./chunks/framework.DCJ5T8RY.js";const k=JSON.parse('{"title":"使用FlatList(ScrollView)的一个小问题","description":"","frontmatter":{"title":"使用FlatList(ScrollView)的一个小问题","date":"2018-05-19"},"headers":[],"relativePath":"2018/flatlist-scrollview-issue.md","filePath":"2018/flatlist-scrollview-issue.md","lastUpdated":1786185344000}'),l={name:"2018/flatlist-scrollview-issue.md"};function n(o,i,r,h,d,c){return t(),e("div",null,[...i[0]||(i[0]=[a(`<h5 id="问题描述" tabindex="-1">问题描述 <a class="header-anchor" href="#问题描述" aria-label="Permalink to &quot;问题描述&quot;">​</a></h5><p>列表 FlatList 直接放在 View 里面，无法 pull to refresh</p><h5 id="原因排查" tabindex="-1">原因排查 <a class="header-anchor" href="#原因排查" aria-label="Permalink to &quot;原因排查&quot;">​</a></h5><p>因为 FlatList 基于 ScrollView 和 VirtualizedList 封装，查看了 ScrollView 的官方文档说明</p><blockquote><p>Keep in mind that <strong><code>ScrollViews must have a bounded height in order to work, since they contain unbounded-height children into a bounded container (via a scroll interaction)[1]</code></strong>. In order to bound the height of a ScrollView, either set the height of the view directly (discouraged) or make sure all parent views have bounded height. <strong><code>Forgetting to transfer {flex: 1} down the view stack can lead to errors here, which the element inspector makes easy to debug</code></strong>.</p></blockquote><h5 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h5><p>在 FlatList 外层的容器里加上<code>{flex：1}</code></p><div class="language-jsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line highlighted"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">View</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> style</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{flex:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">FlatList</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">    ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">View</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h5 id="问题引申" tabindex="-1">问题引申 <a class="header-anchor" href="#问题引申" aria-label="Permalink to &quot;问题引申&quot;">​</a></h5><ol><li>FlatList 和 ScrollView 都必须包裹在有<strong>确定高度</strong>的容器内才能正常工作<br> 所以，如果 FlatList 内嵌在 ScrollView 里，或者反之，内嵌的控件无法正常工作，因为 FlatList 或 ScrollView 都是不固定高度的。 之前也遇到过类似情况，无意中将 FlatList 放在了基于 ScrollView 封装的容器里，只要上拉加载更多，就会出现 FlatList 无穷加载的情况</li><li>FlatList 和 ScrollView 都必须放在<code>{flex:1}</code>的容器里，否则无法正常工作</li></ol>`,10)])])}const g=s(l,[["render",n]]);export{k as __pageData,g as default};
